"""The generated pyapp/generated/pyproject.toml.

developer_settings.py ("packages", python_version) is the only place people edit. pyproject.toml
is generated from it for uv. Its header records the package list it was generated from, so a
change made to the file itself (e.g. "uv add" in a terminal) can be told apart from a change in
developer_settings.py and copied back into the settings.
"""

from __future__ import annotations

import json
import re
import sys
from pathlib import Path
from types import ModuleType, SimpleNamespace
from typing import Iterator, List, Match, Optional, Sequence, Tuple, Union

from pyapp.DONT_CHANGE.backend_settings import PYPROJECT_PATH
from pyapp.DONT_CHANGE.scripts.config import settings
from pyapp.DONT_CHANGE.scripts.console_tools import print_info, print_warn

GENERATED_FROM_MARKER = "# generated-from-packages: "


PYPROJECT_TEMPLATE = """# GENERATED by the launcher from developer_settings.py ("packages" and python_version).
# Do not edit: change "packages" in developer_settings.py or use the dev tools. Changes made
# here anyway (for example with "uv add" in a terminal) are copied into developer_settings.py.
{marker}{base}
[project]
name = "pyapp"
version = "0.1.0"
requires-python = "{requires}"
dependencies = {dependencies}

[tool.uv]
package = false
"""


def requires_python_for(version: Tuple[int, ...]) -> str:
    return f"=={version[0]}.{version[1]}.*"


def read_pyproject() -> str:
    with Path(PYPROJECT_PATH).open(encoding="utf-8") as stream:
        return stream.read()


def write_pyproject(text: str) -> None:
    with Path(PYPROJECT_PATH).open("w", encoding="utf-8", newline="\n") as stream:
        stream.write(text)


def toml_string(value: str) -> str:
    """A TOML basic string.

    JSON's escapes are TOML's, with two exceptions handled here: ASCII escaping would turn a
    character beyond U+FFFF into a surrogate pair, which TOML rejects, so non-ASCII text stays as
    it is; and DEL, which JSON leaves unescaped, is a control character that TOML requires escaped.
    """
    return json.dumps(value, ensure_ascii=False).replace("\x7f", "\\u007F")


def render_pyproject(packages: Sequence[str], requires: str) -> str:
    """pyproject.toml text for a package list."""
    dependencies = "[\n" + "".join(f"    {toml_string(p)},\n" for p in packages) + "]" if packages else "[]"
    return PYPROJECT_TEMPLATE.format(
        marker=GENERATED_FROM_MARKER, base=json.dumps(list(packages)), requires=requires, dependencies=dependencies
    )


def _recorded_packages(text: str) -> Optional[List[str]]:
    """The package list the file was generated from, or None if the marker line is missing."""
    for line in text.splitlines():
        if line.startswith(GENERATED_FROM_MARKER):
            try:
                value = json.loads(line[len(GENERATED_FROM_MARKER) :])
            except ValueError:
                return None
            return value if isinstance(value, list) and all(isinstance(v, str) for v in value) else None
    return None


def reconcile_pyproject(
    s: Optional[Union[ModuleType, SimpleNamespace]] = None, version: Optional[Tuple[int, ...]] = None
) -> Union[ModuleType, SimpleNamespace]:
    """Generate pyproject.toml from developer_settings.py; copy edits made to the file into the settings.

    version: the project's Python, used for requires-python (default: keep the file's value, or the
    launcher's own Python on the first run). Returns the settings module, reloaded if it was edited.
    """
    from pyapp.DONT_CHANGE.scripts.config import all_packages, requirements_file_entries, set_list_setting

    s = s or settings()
    wanted = all_packages(s)
    requires = requires_python_for(version) if version else None
    if Path(PYPROJECT_PATH).is_file():
        text = read_pyproject()
        in_file = declared_dependencies(text)
        recorded = _recorded_packages(text)
        if recorded is None:
            recorded = wanted  # no generator marker: treat it as unchanged, the settings win
        if in_file != recorded and wanted == recorded:
            print_info(
                "Copied package changes made in pyproject.toml (e.g. with uv add) into developer_settings.py: "
                + _change_summary(wanted, in_file)
            )
            # The packages of requirements_path stay in that file, which the launcher never writes.
            from_file = requirements_file_entries(s)
            removed_from_file = [p for p in from_file if p not in in_file]
            if removed_from_file:
                print_warn(
                    "Kept because they are in the requirements_path file (remove them there): "
                    + ", ".join(removed_from_file)
                )
            set_list_setting("packages", [p for p in in_file if p not in from_file])
            s = settings()
            wanted = all_packages(s)
        elif in_file not in (recorded, wanted):
            ignored = [p for p in in_file if p not in wanted]
            print_warn(
                "The packages were changed both in developer_settings.py and in pyproject.toml; "
                "developer_settings.py wins." + (" Not taken over: " + ", ".join(ignored) if ignored else "")
            )
        requires = requires or current_requires_python(text)
    requires = requires or requires_python_for(sys.version_info[:2])
    new_text = render_pyproject(wanted, requires)
    if not Path(PYPROJECT_PATH).is_file() or read_pyproject() != new_text:
        _warn_about_dropped_sources(read_pyproject() if Path(PYPROJECT_PATH).is_file() else "")
        write_pyproject(new_text)
    return s


def _warn_about_dropped_sources(text: str) -> None:
    """Say so when regenerating drops the sources that e.g. "uv add --git" wrote.

    They are not kept on purpose: pyproject.toml is not committed, so another PC would silently
    get the packages from PyPI instead. A direct reference in "packages" is committed and works
    everywhere.
    """
    if re.search(r"(?m)^\[tool\.uv\.sources", text):
        print_warn(
            "pyproject.toml had package sources ([tool.uv.sources], e.g. from uv add --git); they are not kept. "
            'Put the package into "packages" as a direct reference instead, e.g. '
            '"pkg @ git+https://github.com/org/pkg@v1.0".'
        )


def _change_summary(old: Sequence[str], new: Sequence[str]) -> str:
    changes = ["+ " + p for p in new if p not in old] + ["- " + p for p in old if p not in new]
    return ", ".join(changes) or "new order"


def set_requires_python(
    version: Tuple[int, ...], s: Optional[Union[ModuleType, SimpleNamespace]] = None
) -> Union[ModuleType, SimpleNamespace]:
    """Point requires-python at the interpreter's minor version (and regenerate pyproject.toml)."""
    return reconcile_pyproject(s, version)


def current_requires_python(text: Optional[str] = None) -> Optional[str]:
    try:
        text = read_pyproject() if text is None else text
    except OSError:
        return None
    match = re.search(r'(?m)^requires-python\s*=\s*"([^"]*)"', text)
    return match.group(1) if match else None


def version_satisfies_requires(version: Tuple[int, ...], requires: Optional[str]) -> bool:
    """Support the "==X.Y.*" form this launcher writes; other forms are left to uv."""
    if not requires:
        return True
    match = re.fullmatch(r"==\s*(\d+)\.(\d+)\.\*", requires.strip())
    if not match:
        return True
    return version[:2] == (int(match.group(1)), int(match.group(2)))


def declared_dependencies(text: Optional[str] = None) -> List[str]:
    """Return the [project] dependencies strings of pyproject.toml (simple parser for uv-written files)."""
    if text is None:
        try:
            text = read_pyproject()
        except OSError:
            return []
    span = _dependencies_span(text)
    if not span:
        return []
    return [value for kind, _, value in _toml_tokens(text, *span) if kind == "string"]


# A TOML basic string ("..." with backslash escapes) or literal string ('...', no escapes).
_TOML_STRING = re.compile(r'"((?:[^"\\\n]|\\.)*)"|\'([^\'\n]*)\'')


def _toml_string_value(match: Match[str]) -> str:
    basic, literal = match.groups()
    if basic is None:
        return literal
    try:
        return json.loads('"' + basic + '"')  # TOML basic-string escapes are JSON's (plus rare \\U)
    except ValueError:
        return basic


def _toml_tokens(text: str, start: int, end: int) -> Iterator[Tuple[str, int, str]]:
    """Yield (kind, position, string value) for "string", "[" and "]" between start and end; skips comments."""
    index = start
    while index < end:
        char = text[index]
        if char == "#":
            newline = text.find("\n", index, end)
            index = end if newline < 0 else newline + 1
            continue
        if char in "\"'":
            match = _TOML_STRING.match(text, index)
            if match and match.end() <= end:
                yield "string", index, _toml_string_value(match)
                index = match.end()
                continue
        if char in "[]":
            yield char, index, ""
        index += 1


def _dependencies_span(text: str) -> Optional[Tuple[int, int]]:
    """Locate the value of dependencies = [...] inside [project]."""
    project = re.search(r"(?m)^\[project\]\s*$", text)
    if not project:
        return None
    following = re.search(r"(?m)^\[", text[project.end() :])
    end_of_table = project.end() + following.start() if following else len(text)
    key = re.compile(r"(?m)^dependencies\s*=\s*\[").search(text, project.end(), end_of_table)
    if not key:
        return None
    start = key.end() - 1
    depth = 0
    for kind, index, _ in _toml_tokens(text, start, end_of_table):
        if kind == "[":
            depth += 1
        elif kind == "]":
            depth -= 1
            if depth == 0:
                return start, index + 1
    return None


def clear_dependencies() -> None:
    """Empty the package list in developer_settings.py (and pyproject.toml)."""
    from pyapp.DONT_CHANGE.scripts.config import requirements_file_entries, set_list_setting

    if set_list_setting("packages", []):
        print_info('Emptied "packages" in developer_settings.py.')
    if requirements_file_entries(settings()):
        print_info("The packages of the requirements_path file stay; empty that file to remove them too.")
    reconcile_pyproject(settings())
